import app from 'flarum/forum/app';
import Page from 'flarum/common/components/Page';
import Link from 'flarum/common/components/Link';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';

/** /arac — marka, model, firma, plaka, şehir ve yıl derlemelerinin dizini. */
export default class HubIndexPage extends Page {
  oninit(vnode) {
    super.oninit(vnode);
    this.groups = app.data.framioHubIndex || null;
    delete app.data.framioHubIndex;
    app.setTitle('Araçlar');
    app.setTitleCount(0);
    if (!this.groups) {
      app.request({
        method: 'GET',
        url: app.forum.attribute('apiUrl') + '/seo/hubs'
      }).then(res => {
        this.groups = res.data;
        m.redraw();
      }).catch(() => {
        this.groups = [];
        m.redraw();
      });
    }
  }
  path(url) {
    const base = app.forum.attribute('baseUrl');
    return url.indexOf(base) === 0 ? url.substr(base.length) || '/' : url;
  }
  view() {
    return m("div", {
      className: "FramioHubPage container"
    }, m("h1", {
      className: "FramioHubPage-title"
    }, "Marka, model, firma, plaka, \u015Fehir ve y\u0131la g\xF6re ara\xE7 foto\u011Fraflar\u0131"), !this.groups ? m(LoadingIndicator, null) : this.groups.filter(g => g.items && g.items.length).map(g => m("section", {
      className: "FramioHubPage-group",
      id: g.path
    }, m("h2", null, g.label), m("ul", {
      className: "FramioHubPage-tags"
    }, g.items.map(it => m("li", null, m(Link, {
      href: this.path(it.url)
    }, it.name), " ", m("span", null, it.posts)))))));
  }
}
flarum.reg.add('framio-seo-pack', 'forum/components/HubIndexPage', HubIndexPage);